#include "tapesister/ts_editor.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <string.h>
int main(void){size_t n=0;const ts_parameter_desc*d=ts_parameter_descriptors(&n);assert(n==TS_PARAMETER_COUNT);bool seen[TS_PARAMETER_COUNT]={0};for(size_t i=0;i<n;i++){assert(d[i].id==(ts_parameter_id)i&&!seen[i]);seen[i]=true;assert(d[i].page<TS_EDITOR_PAGE_COUNT);if(d[i].type==TS_PARAM_ENUM){assert(d[i].enum_count==(size_t)(d[i].maximum+1));for(size_t j=0;j<d[i].enum_count;j++)assert(d[i].enum_labels[j][0]);}}assert(ts_parameter_to_position(ts_parameter_by_id(TS_P_FILTER_CUTOFF),20)==0);assert(fabs(ts_parameter_to_position(ts_parameter_by_id(TS_P_FILTER_CUTOFF),86400)-1)<1e-12);ts_owned_recipe a={0},b={0};assert(ts_owned_recipe_copy(&a,ts_fixture_recipe(0)));assert(ts_owned_recipe_copy(&b,&a.value));assert(a.name!=b.name&&ts_recipe_fields_equal(&a.value,&b.value));double v;assert(ts_parameter_get_number(TS_P_HARMONIC_MIX,&a.value,&v));assert(ts_parameter_set_number(TS_P_HARMONIC_MIX,&a.value,v<.9?v+.01:v-.01));assert(!ts_recipe_fields_equal(&a.value,&b.value));assert(!ts_parameter_set_number(TS_P_DRIVE,&a.value,NAN));assert(!ts_parameter_parse(TS_P_DRIVE,&a.value,"999"));ts_recipe_history h={0};for(unsigned i=0;i<140;i++){assert(ts_recipe_history_commit(&h,&a.value));assert(ts_parameter_get_number(TS_P_HARMONIC_MIX,&a.value,&v));v+=.001;if(v>1)v=.001;assert(ts_parameter_set_number(TS_P_HARMONIC_MIX,&a.value,v));}assert(h.undo_count==128);assert(ts_recipe_history_undo(&h,&a));assert(h.redo_count==1);assert(ts_recipe_history_commit(&h,&a.value)&&h.redo_count==0);ts_recipe_history_destroy(&h);ts_owned_recipe_destroy(&a);ts_owned_recipe_destroy(&b);puts("editor tests passed");}
